<form class="row g-2 mb-3" method="get"><div class="col-md-5"><input name="q" class="form-control" placeholder="Search goods receipt no., supplier or challan no." value="<?= e($q) ?>"></div><div class="col-auto"><button class="btn btn-outline-secondary">Search</button></div></form>
<p class="text-muted">Choose the goods receipt the items came in on.</p>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0 align-middle"><thead><tr><th>Receipt</th><th>Date</th><th>Supplier</th><th>Challan</th><th class="text-end">Can still return</th><th></th></tr></thead><tbody>
  <?php foreach ($rows as $r): ?><tr><td><?= e($r['grn_no']) ?></td><td><?= e($r['received_date']) ?></td><td><?= e($r['supplier']) ?></td><td><?= e($r['supplier_ref'] ?? '') ?></td><td class="text-end"><?= e(qty($r['returnable'])) ?></td>
    <td class="text-end"><?php if ($r['returnable'] > 0): ?><a class="btn btn-sm btn-outline-danger" href="<?= url('purchase/returns/create?grn=' . (int)$r['id']) ?>">Return from this</a><?php endif; ?></td></tr><?php endforeach; ?>
  <?php if (!$rows): ?><tr><td colspan="6" class="text-muted">No goods receipts found.</td></tr><?php endif; ?></tbody></table></div></div>
